bounded_host_request.command:
set -euo pipefail
cd "$HOME/Project/Gserver/projects/TGtumbler/GateApp-Bot"
test "$(docker inspect -f '{{.State.Running}}' deploy-postgres-1)" = true
docker exec deploy-postgres-1 psql -X -v ON_ERROR_STOP=1 -U gace -d gaybbs -Atqc "
SELECT 'verified_announcement_by_board',board_key,count(*) FROM posting_topics WHERE purpose='announcement' AND enabled AND verified_at IS NOT NULL AND verified_by IS NOT NULL GROUP BY board_key ORDER BY board_key;
SELECT 'published_doorways_total',count(*) FROM topic_dm_entry_pins WHERE state='published' AND pinned;
SELECT 'published_doorways_with_announcement_route',count(*) FROM topic_dm_entry_pins p WHERE p.state='published' AND p.pinned AND EXISTS(SELECT 1 FROM posting_topics t WHERE t.chat_id=p.chat_id AND t.message_thread_id=p.message_thread_id AND t.purpose='announcement' AND t.enabled AND t.verified_by IS NOT NULL AND t.verified_at IS NOT NULL);
SELECT 'active_entry_without_announcement_route',count(*) FROM topic_dm_entry_sessions s JOIN topic_dm_entry_pins p ON p.token_hash=s.token_hash AND p.state='published' AND p.pinned WHERE s.expires_at>NOW() AND NOT EXISTS(SELECT 1 FROM posting_topics t WHERE t.chat_id=s.chat_id AND t.message_thread_id=s.message_thread_id AND t.purpose='announcement' AND t.enabled AND t.verified_by IS NOT NULL AND t.verified_at IS NOT NULL);
"
